&lt;p&gt;&lt;span class="EOP Selected SCXW260952635 BCX8" data-ccp-props="{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}"&gt;&lt;span class="NormalTextRun SCXW104050567 BCX8"&gt;Projects the Engineering Lead &lt;/span&gt;&lt;span class="NormalTextRun SCXW104050567 BCX8"&gt;might lead or deliver as individual contributor include:&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span class="EOP Selected SCXW260952635 BCX8" data-ccp-props="{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}"&gt;&lt;span class="TextRun SCXW90952646 BCX8" lang="EN-GB" data-contrast="none"&gt;&lt;span class="NormalTextRun SCXW90952646 BCX8"&gt;Designing the scalable system architecture&lt;/span&gt; &lt;span class="NormalTextRun SCXW90952646 BCX8"&gt;underpinning the repeatable delivery and analysis of model &lt;/span&gt;&lt;span class="NormalTextRun CommentStart SCXW90952646 BCX8"&gt;evaluations&lt;/span&gt; &lt;span class="NormalTextRun SCXW90952646 BCX8"&gt;and benchmarks&lt;/span&gt;&lt;span class="NormalTextRun SCXW90952646 BCX8"&gt;.&lt;/span&gt;&lt;/span&gt;&lt;span class="EOP Selected SCXW90952646 BCX8" data-ccp-props="{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559739&amp;quot;:0}"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
