&lt;li&gt;&lt;span class="EOP Selected SCXW260952635 BCX8" data-ccp-props="{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}"&gt;&lt;span class="EOP Selected SCXW179107279 BCX8" data-ccp-props="{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559739&amp;quot;:0}"&gt;&lt;span class="TextRun SCXW179280954 BCX8" lang="EN-GB" data-contrast="auto"&gt;&lt;span class="NormalTextRun SCXW179280954 BCX8"&gt;Designing and building a toolkit for multi-agent studies, which allows researchers to run synthetic as well as human-in-the-loop studies seamlessly and with performance guarantees.&lt;/span&gt;&lt;/span&gt;&lt;span class="EOP Selected SCXW179280954 BCX8" data-ccp-props="{&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559739&amp;quot;:0}"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
